"""PAC ACARS 1.0.8: the altitude shown matches the cockpit altimeter (the flight level at cruise), not the true
height above sea level.
Run from the PAC folder (on the server, and on the Windows PC you build PAC ACARS on):   python pac_acars_108.py
Backups: <file>.bak-acars108. Safe to run twice."""
import base64, json, os, re, shutil, sys
ROOT = sys.argv[1] if len(sys.argv) > 1 else "."
D = json.loads(base64.b64decode(""))
bad, done = [], 0
for rel, hunks in D["pairs"].items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p):
        if not rel.startswith("acars_client/build"): bad.append(rel + " (not found)")
        continue   # the build files only exist on the PC that builds PAC ACARS
    s = open(p, encoding="utf-8", newline="").read(); o = s
    crlf = "\r\n" in s
    if crlf: s = s.replace("\r\n", "\n")
    for old, new in hunks:
        if new in s: continue
        if s.count(old) != 1:
            bad.append(rel + ": " + repr(old.strip()[:70])); continue
        s = s.replace(old, new); done += 1
    if crlf: s = s.replace("\n", "\r\n")
    if s != o:
        if not os.path.exists(p + ".bak-acars108"): shutil.copyfile(p, p + ".bak-acars108")
        open(p, "w", encoding="utf-8", newline="").write(s)
# version 1.0.8 in the build files, whatever they said before
for rel, pats in {"acars_client/client.py": [(r'(\nVERSION = ")[0-9.]+"', r'\g<1>1.0.8"')], "acars_client/build/version_info.txt": [(r"(Version', ')[0-9.]+'", r"\g<1>1.0.8'"), (r"(vers=\()[0-9, ]+(\))", r"\g<1>1, 0, 8, 0\2")],
                  "acars_client/build/installer.iss": [(r'(#define AppVersion ")[0-9.]+"', r'\g<1>1.0.8"')],
                  "acars_client/build/build_acars.bat": [(r'(set "VERSION=)[0-9.]+"', r'\g<1>1.0.8"')]}.items():
    p = os.path.join(ROOT, rel)
    if not os.path.exists(p): continue
    s = open(p, encoding="utf-8", newline="").read(); o = s
    for a, b in pats: s = re.sub(a, b, s)
    if s != o:
        if not os.path.exists(p + ".bak-acars108"): shutil.copyfile(p, p + ".bak-acars108")
        open(p, "w", encoding="utf-8", newline="").write(s); done += 1
c = os.path.join(ROOT, "acars_client", "CHANGELOG.txt")
if os.path.isdir(os.path.dirname(c)):
    old = open(c, encoding="utf-8").read() if os.path.exists(c) else ""
    if "1.0.8" not in old: open(c, "w", encoding="utf-8").write(D["changelog"] + ("\n" + old.split("\n", 3)[-1] if old else "")); done += 1
t = os.path.join(ROOT, "tests", "test_altitude.py")
if os.path.isdir(os.path.dirname(t)): open(t, "w", encoding="utf-8").write(D["test"])
print("PAC ACARS 1.0.8 UPDATE APPLIED (%d changes)" % done if not bad else "PROBLEMS:\n  " + "\n  ".join(bad))
